    region3_times = [];
    region4_times = [];
    region5_times = [];
    region6_times = [];
    region7_times = [];
    region8_times = [];
    region9_times = [];
    for person in person_dict_list {
        for key in person {
            if (key == 1) {
                region1_times.append(person[key]);
            } elif (key == 2) {
                region2_times.append(person[key]);
            } elif (key == 3) {
                region3_times.append(person[key]);
