"""
    Parameters
    ----------
    text: str of nominal values for a single mushroom species from primary_data_edited.csv

    Returns
    -------
    replace commas outside of angular brackets with semicolons (but not inside of them)

    Example
    -------
    text = "[a, b], [c, d]"
    return: "[a, b]; [c, d]"
    """
def replace_comma_in_text(text: Any) -> object {
    result_text = "";
    replace = True;
    for sign in text {
        if (sign == '[') {
            replace = False;
        }
        if (sign == ']') {
            replace = True;
        }
        if (sign == ',') {
            if replace {
                result_text += ';';
            } else {
                result_text += sign;
            }
        } else {
            result_text += sign;
        }
    }
    return result_text;
}

"""Exchange the smallest prefixes of first and second that have equal sum.

    >>> a = [1, 1, 3, 2, 1, 1, 4]
    >>> b = [4, 3, 2, 7]
    >>> trade(a, b) # Trades 1+1+3+2=7 for 4+3=7
    'Deal!'
    >>> a
    [4, 3, 1, 1, 4]
    >>> b
    [1, 1, 3, 2, 2, 7]
    >>> c = [3, 3, 2, 4, 1]
    >>> trade(b, c)
    'No deal!'
    >>> b
    [1, 1, 3, 2, 2, 7]
    >>> c
    [3, 3, 2, 4, 1]
    >>> trade(a, c)
    'Deal!'
    >>> a
    [3, 3, 2, 1, 4]
    >>> b
    [1, 1, 3, 2, 2, 7]
    >>> c
    [4, 3, 1, 4, 1]
    """
def trade(first: Any, second: Any) -> object {
    (m, n) = (1, 1);
    """
    This function tries to find the indicies that result in an equal sum starting from
    the beginning of the lists. If either sides of the sums are smaller, the respective
    index is incremented. If either of the indicies pass the boundaries of the list, then
    an equal sum cannot be found.
    """;
    def find_equal_sum_partitions(fir: Any, sec: Any) -> object {
        (fi, si) = (1, 1);
        while ((fi < len(fir)) and (si < len(sec))) {
            (sumfi, sumsi) = (sum(fir[:fi]), sum(sec[:si]));
            if (sumfi < sumsi) {
                fi += 1;
            } elif (sumfi > sumsi) {
                si += 1;
            } else {
                return (fi, si);
            }
        }
        return (None, None);
    }
    (m, n) = find_equal_sum_partitions(first, second);
    if (None not in [m, n]) {
        (first[:m], second[:n]) = (second[:n], first[:m]);
        return 'Deal!';
    } else {
        return 'No deal!';
    }
}
